// WF-P2 "Channel checks" (Code node, Run Once for All Items).
// SOP section 5, step 1: open the channel, check the subscriber count, skip if outside the range.
// Input: one YouTube channels.list response for up to 50 channels. Output: one item per podcast_leads row:
//   { id, channel_id, ok, patch?, …channel facts }   ok=false rows carry the `patch` that marks them skipped.

const cfg = $('Settings').first().json
const found = $('Fetch found podcasts').all().map(i => i.json).filter(r => r && r.id)
const res = $input.first().json || {}
const channels = new Map((Array.isArray(res.items) ? res.items : []).map(c => [c.id, c]))
const MIN = Number(cfg.min_subscribers) || 1000
const MAX = Number(cfg.max_subscribers) || 25000
const apiError = res.error ? String(res.error.message || res.error).slice(0, 200) : null

const skip = (row, reason, extra = {}) => ({
  json: { id: row.id, channel_id: row.youtube_channel_id, ok: false, skip_reason: reason, patch: { stage: 'skipped', skip_reason: reason, ...extra } },
})

const out = []
for (const row of found) {
  // A failed API call leaves the rows as 'found' so the next run retries them.
  if (apiError) continue
  const ch = channels.get(row.youtube_channel_id)
  if (!ch) {
    out.push(skip(row, 'Channel not found on YouTube'))
    continue
  }
  const sn = ch.snippet || {}
  const st = ch.statistics || {}
  const subs = st.hiddenSubscriberCount ? null : Number(st.subscriberCount)
  const facts = {
    podcast_name: String(sn.title || row.podcast_name || '').slice(0, 200) || null,
    youtube_channel_url: sn.customUrl ? `https://www.youtube.com/${sn.customUrl.startsWith('@') ? sn.customUrl : '@' + sn.customUrl}` : `https://www.youtube.com/channel/${ch.id}`,
    subscribers: Number.isFinite(subs) ? subs : null,
    description: String(sn.description || (ch.brandingSettings && ch.brandingSettings.channel && ch.brandingSettings.channel.description) || '').slice(0, 5000),
  }
  if (subs === null || !Number.isFinite(subs)) {
    out.push(skip(row, 'Subscriber count hidden', facts))
    continue
  }
  if (subs < MIN || subs > MAX) {
    out.push(skip(row, `${subs.toLocaleString('en-US')} subscribers (want ${MIN.toLocaleString('en-US')}–${MAX.toLocaleString('en-US')})`, facts))
    continue
  }
  const uploads = ch.contentDetails && ch.contentDetails.relatedPlaylists && ch.contentDetails.relatedPlaylists.uploads
  if (!uploads) {
    out.push(skip(row, 'No uploads playlist', facts))
    continue
  }
  out.push({
    json: {
      id: row.id,
      channel_id: ch.id,
      ok: true,
      niche: row.niche,
      uploads_playlist: uploads,
      // Every channel's Shorts live in an auto-made playlist "UUSH" + channel id without its "UC" prefix.
      shorts_playlist: 'UUSH' + ch.id.slice(2),
      custom_url: sn.customUrl || null,
      default_language: sn.defaultLanguage || null,
      country: sn.country || null,
      ...facts,
    },
  })
}

// On an API error nothing is output (Run summary reports it from the channels response).
return out

// WF-P2 "SOP checks" (Code node, Run Once for Each Item).
// SOP section 5, steps 2–6 for one channel: episodes in the last 30 days, episode length, Shorts tab,
// About links (Instagram, email, host's other channel) and one recent full episode as the sample.
// Input ($json): the Shorts playlist response. Output: { id, hard_skip, patch?, facts…, prompt }.

const cfg = $('Settings').first().json
const ch = $('Channel checks').item.json
const details = $('Video details').item.json || {}
const shortsRes = $json || {}
const DAY = 86400000
const now = Date.now()
const MIN_UPLOADS = Number(cfg.min_uploads_30d) || 2
const MIN_MINUTES = Number(cfg.min_episode_minutes) || 30

// ISO 8601 duration ("PT1H2M3S") -> seconds
const seconds = d => {
  const m = String(d || '').match(/P(?:(\d+)D)?T?(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/)
  return m ? (+m[1] || 0) * 86400 + (+m[2] || 0) * 3600 + (+m[3] || 0) * 60 + (+m[4] || 0) : 0
}

// Shorts: the auto "UUSH…" playlist. It returns 404 when the channel has none.
const shortItems = Array.isArray(shortsRes.items) ? shortsRes.items : []
const shortIds = new Set(shortItems.map(s => s.contentDetails && s.contentDetails.videoId).filter(Boolean))
const shorts30 = shortItems.filter(s => {
  const t = Date.parse((s.contentDetails && s.contentDetails.videoPublishedAt) || (s.snippet && s.snippet.publishedAt) || '')
  return t && now - t <= 30 * DAY
}).length
// None: empty Shorts tab. Good: a steady shorts habit (2+ a week) — SOP says skip those. Poor: anything in between.
const hasShorts = shortItems.length === 0 ? 'None' : shorts30 >= 8 ? 'Good' : 'Poor'

const videos = (Array.isArray(details.items) ? details.items : []).map(v => ({
  id: v.id,
  title: String((v.snippet && v.snippet.title) || ''),
  description: String((v.snippet && v.snippet.description) || ''),
  published: Date.parse((v.snippet && v.snippet.publishedAt) || '') || 0,
  secs: seconds(v.contentDetails && v.contentDetails.duration),
  views: Number(v.statistics && v.statistics.viewCount) || 0,
  live: v.snippet && v.snippet.liveBroadcastContent,
  lang: (v.snippet && (v.snippet.defaultAudioLanguage || v.snippet.defaultLanguage)) || null,
}))
// Episodes = full videos (10+ minutes, not a Short, not an upcoming premiere/live).
const episodes = videos.filter(v => !shortIds.has(v.id) && v.secs >= 600 && v.live !== 'upcoming' && v.live !== 'live').sort((a, b) => b.published - a.published)
const recent = episodes.filter(v => now - v.published <= 30 * DAY)
const last = episodes[0] ? episodes[0].published : 0
const sampleSet = episodes.slice(0, 10)
const avgMinutes = sampleSet.length ? Math.round(sampleSet.reduce((s, v) => s + v.secs, 0) / sampleSet.length / 60) : 0

// SOP step 6: one recent FULL episode, preferably from the last 30 days and 30+ minutes; the most-viewed of those.
const pool = recent.filter(v => v.secs >= MIN_MINUTES * 60)
const sample = (pool.length ? pool : recent.length ? recent : episodes.slice(0, 3)).slice().sort((a, b) => b.views - a.views)[0] || null

// SOP step 4: About links. The API has no "links" section, so read the channel description and the
// latest episode descriptions (shows nearly always put their Instagram and email there).
const texts = [ch.description || '', ...episodes.slice(0, 6).map(v => v.description)]
const count = (re, pick, skipFn) => {
  const tally = new Map()
  texts.forEach((t, i) => {
    for (const m of t.matchAll(re)) {
      const v = pick(m)
      if (!v || (skipFn && skipFn(v))) continue
      tally.set(v, (tally.get(v) || 0) + (i === 0 ? 3 : 1)) // the channel's own description counts more
    }
  })
  return [...tally.entries()].sort((a, b) => b[1] - a[1]).map(e => e[0])
}
const IG_RESERVED = new Set(['p', 'reel', 'reels', 'explore', 'stories', 'tv', 'accounts', 'direct', 'about', 'legal'])
const instagram = count(/instagram\.com\/([A-Za-z0-9_.]{2,30})/gi, m => m[1].replace(/\.+$/, '').toLowerCase(), v => IG_RESERVED.has(v))
const emails = count(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, m => m[0].toLowerCase().replace(/\.+$/, ''),
  v => /\.(png|jpe?g|gif|webp)$/.test(v) || /(example\.|youtube\.com|sentry|noreply|no-reply)/.test(v))
const own = String(ch.custom_url || '').replace(/^@/, '').toLowerCase()
const otherYt = count(/youtube\.com\/(@[\w.-]+|channel\/UC[\w-]{20,}|c\/[\w.-]+)/gi, m => m[1], v =>
  v.toLowerCase() === '@' + own || v.toLowerCase() === 'c/' + own || v.includes(ch.channel_id))

const facts = {
  subscribers: ch.subscribers,
  uploads_30d: recent.length,
  avg_minutes: avgMinutes,
  has_shorts: hasShorts,
  shorts_30d: shorts30,
  last_upload_at: last ? new Date(last).toISOString() : null,
  instagram_url: instagram[0] ? `https://www.instagram.com/${instagram[0]}` : null,
  email: emails[0] || null,
  host_other_url: otherYt[0] ? `https://www.youtube.com/${otherYt[0]}` : 'same',
  sample_episode_url: sample ? `https://www.youtube.com/watch?v=${sample.id}` : null,
  sample_episode_title: sample ? sample.title.slice(0, 300) : null,
  podcast_name: ch.podcast_name,
  youtube_channel_url: ch.youtube_channel_url,
  description: ch.description,
}

// Hard skips straight from the SOP ("Skip" column), no AI needed.
let hard = null
if (!episodes.length) hard = 'No full-length episodes found'
else if (now - last > 60 * DAY) hard = 'No upload in 60 days'
else if (hasShorts === 'Good') hard = `Already posts Shorts regularly (${shorts30} in 30 days)`
else if (avgMinutes < 10) hard = `Episodes are short (${avgMinutes} min average)`
else if (!sample) hard = 'No recent full episode to sample'

// Soft checks: failing two or more skips the show (SOP: "If a show fails two or more checks, skip it").
const fails = []
if (recent.length < MIN_UPLOADS) fails.push(`only ${recent.length} episode${recent.length === 1 ? '' : 's'} in 30 days`)
if (avgMinutes < MIN_MINUTES) fails.push(`episodes average ${avgMinutes} min`)
if (!facts.instagram_url) fails.push('no Instagram link found')

const prompt = [
  `Channel: ${ch.podcast_name}`,
  `Niche searched: ${ch.niche || 'unknown'}`,
  `Subscribers: ${ch.subscribers}`,
  `Channel country: ${ch.country || 'unknown'}; channel language: ${ch.default_language || 'unknown'}; latest video language: ${(episodes[0] && episodes[0].lang) || 'unknown'}`,
  `Episodes in last 30 days: ${recent.length}; average length: ${avgMinutes} min; Shorts in last 30 days: ${shorts30}`,
  `Channel description:\n${String(ch.description || '').slice(0, 1500)}`,
  `Latest episode titles:\n${episodes.slice(0, 8).map(v => `- ${v.title} (${Math.round(v.secs / 60)} min, ${v.views} views)`).join('\n')}`,
  `Latest episode description:\n${String((episodes[0] && episodes[0].description) || '').slice(0, 1200)}`,
].join('\n\n')

return {
  json: {
    id: ch.id,
    hard_skip: !!hard,
    fails,
    facts,
    prompt,
    patch: hard ? { stage: 'skipped', skip_reason: hard, checks_failed: fails, ...facts } : null,
  },
}

// WF-P2 "Build row" (Code node, Run Once for Each Item).
// Adds the AI's judgement (format, language, network-owned, host name, "Why a fit") to the SOP checks
// and decides qualified vs skipped. Output: { id, patch } for the podcast_leads row.

const prep = $('SOP checks').item.json
const res = $json || {}
const facts = prep.facts
const fails = [...prep.fails]

let ai = null
let aiError = null
try {
  const raw = String(res.choices[0].message.content || '')
  const block = raw.match(/\{[\s\S]*\}/)
  ai = JSON.parse(block ? block[0] : raw)
} catch {
  aiError = res.error ? String(res.error.message || res.error).slice(0, 200) : 'Could not read the AI answer'
}

const patch = { ...facts, checks_failed: fails }
let hard = null
if (ai) {
  if (ai.is_podcast === false) hard = 'Not a podcast'
  else if (ai.network_owned === true) hard = 'Owned by a network or brand'
  if (ai.english === false) fails.push('not in English')
  if (['audio-only', 'music', 'other'].includes(String(ai.format))) fails.push(`format: ${ai.format}`)
  patch.host_name = typeof ai.host_name === 'string' && ai.host_name.trim() && !/unknown/i.test(ai.host_name) ? ai.host_name.trim().slice(0, 120) : null
  patch.language = ai.english === false ? 'other' : 'English'
  patch.format = typeof ai.format === 'string' ? ai.format.slice(0, 40) : null
  patch.network_owned = ai.network_owned === true
  const score = Number(ai.score)
  patch.ai_score = Number.isFinite(score) ? Math.max(0, Math.min(100, Math.round(score))) : null
}

const contact = [facts.email ? 'Email in description' : null, facts.instagram_url ? 'IG DM (check it is open)' : 'IG not found: search by hand']
patch.contact_method = contact.filter(Boolean).join(' · ')
// Instagram activity cannot be checked automatically (no public API): someone confirms it in the dashboard.
patch.ig_verified = false
patch.checks_failed = fails

if (hard || fails.length >= 2) {
  patch.stage = 'skipped'
  patch.skip_reason = hard || `Failed ${fails.length} checks: ${fails.join('; ')}`
} else {
  patch.stage = 'qualified'
  patch.skip_reason = null
  const line = ai && typeof ai.why_fit === 'string' ? ai.why_fit.replace(/\s+/g, ' ').trim().slice(0, 200) : `${facts.uploads_30d} eps/month, ${facts.avg_minutes}-min episodes, Shorts: ${facts.has_shorts}`
  // SOP quality rule: not sure -> add it with "Unsure" in Why a fit, never leave it out silently.
  const unsure = !ai || ai.unsure === true || fails.length === 1
  patch.why_fit = (unsure ? `Unsure (${aiError || fails[0] || 'AI unsure'}): ` : '') + line
}

return { json: { id: prep.id, patch } }

// WF-P2 "Run summary" (Code node, Run Once for All Items). Runs after every channel was checked and saved.
const cfg = $('Config').first().json
const ran = name => {
  try {
    return $(name).isExecuted ? $(name).all().map(i => i.json) : []
  } catch {
    return []
  }
}
const channelsRes = ran('YouTube: channels')[0] || {}
const early = ran('Channel checks').filter(r => r && r.ok === false)
const hard = ran('SOP checks').filter(r => r && r.hard_skip)
const built = ran('Build row').filter(r => r && r.patch)
const qualified = built.filter(r => r.patch.stage === 'qualified').length
const skipped = early.length + hard.length + built.length - qualified
const errors = []
if (channelsRes.error) errors.push({ message: `YouTube channels: ${String(channelsRes.error.message || channelsRes.error).slice(0, 200)}` })
return [{
  json: {
    workflow_name: 'WF-P2-PodcastQualify',
    status: errors.length ? 'failed' : 'success',
    leads_scraped: 0,
    leads_scored: qualified,
    leads_skipped: skipped,
    emails_sent: 0,
    replies_detected: 0,
    errors: errors.length ? errors : null,
    started_at: cfg.started_at,
    finished_at: new Date().toISOString(),
  },
}]

// Podcast "Settings" (Code node, Run Once for All Items).
// Starts from this workflow's Config node, then applies the dashboard settings saved in Supabase:
//   settings.key = 'outreach' -> shared with the startup pipeline: STOP ALL, timezone, send window, signature
//   settings.key = 'podcast'  -> podcast only: daily limit (10), subscriber range, searches per run, sheet URL, …
// Anything missing or invalid keeps the Config value.
const cfg = { ...$('Config').first().json }
const rows = $input.all().map(i => i.json).filter(r => r && r.key)
const valueOf = key => {
  const r = rows.find(x => x.key === key)
  return r && r.value && typeof r.value === 'object' && !Array.isArray(r.value) ? r.value : {}
}

const num = (min, max) => v => {
  const n = Number(v)
  return v !== '' && v !== null && Number.isFinite(n) && n >= min && n <= max ? Math.round(n) : undefined
}
const bool = v => (typeof v === 'boolean' ? v : undefined)
const text = v => (typeof v === 'string' && v.trim() ? v.trim().slice(0, 300) : undefined)
const days = v => {
  const list = (Array.isArray(v) ? v : String(v).split(',')).map(Number).filter(n => Number.isInteger(n) && n > 0 && n <= 90)
  return list.length ? list.join(',') : '0'
}
const tz = v => {
  try {
    new Intl.DateTimeFormat('en-US', { timeZone: String(v) })
    return String(v)
  } catch {
    return undefined
  }
}

// [dashboard key, Config key, rule]
const SHARED = [
  ['paused', 'paused', bool],
  ['timezone', 'timezone', tz],
  ['send_window_start', 'send_window_start', num(0, 23)],
  ['send_window_end', 'send_window_end', num(1, 24)],
  ['send_on_weekends', 'send_on_weekends', bool],
  ['from_name', 'from_name', text],
  ['sign_off', 'sign_off', text],
  ['signature_name', 'signature_name', text],
  ['company_name', 'company_name', text],
  ['website', 'website', text],
]
const PODCAST = [
  ['daily_max', 'daily_max', num(1, 50)],
  ['min_subscribers', 'min_subscribers', num(0, 10000000)],
  ['max_subscribers', 'max_subscribers', num(1, 10000000)],
  ['min_uploads_30d', 'min_uploads_30d', num(0, 60)],
  ['min_episode_minutes', 'min_episode_minutes', num(1, 600)],
  ['searches_per_run', 'searches_per_run', num(1, 90)],
  ['follow_up_days', 'follow_up_days', days],
  ['draft_dms', 'draft_dms', bool],
  ['autopilot', 'autopilot', v => (['manual', 'auto'].includes(v) ? v : undefined)],
  ['sheet_url', 'sheet_url', v => (typeof v === 'string' && v.trim() ? v.trim() : undefined)], // empty = keep Config's link
  ['added_by', 'added_by', text],
]

const applied = []
const apply = (saved, list, prefix) => {
  for (const [from, to, rule] of list) {
    if (saved[from] === undefined || saved[from] === null || !(to in cfg)) continue
    const value = rule(saved[from])
    if (value === undefined) continue
    cfg[to] = value
    applied.push(prefix + from)
  }
}
apply(valueOf('outreach'), SHARED, '')
apply(valueOf('podcast'), PODCAST, 'podcast.')

const base = $('Config').first().json
if (cfg.send_window_start !== undefined && Number(cfg.send_window_start) >= Number(cfg.send_window_end)) {
  cfg.send_window_start = base.send_window_start
  cfg.send_window_end = base.send_window_end
}
if (cfg.min_subscribers !== undefined && Number(cfg.min_subscribers) >= Number(cfg.max_subscribers)) {
  cfg.min_subscribers = base.min_subscribers
  cfg.max_subscribers = base.max_subscribers
}
cfg.settings_applied = applied
return [{ json: cfg }]
